  'st.db_title': 'Account del database',
  'st.db_intro': 'Usata solo quando Autenticazione è "Account del database". Gli utenti accedono con un ruolo di login PostgreSQL e la relativa password, verificati tramite una breve connessione a questo database con quel ruolo. I superuser e i ruoli propri di pgkiln vengono sempre rifiutati; se nessuno dei due campi è impostato, nessuno può accedere.',
