  'st.session_group_ph': 'vuoto: non condivisa',
  'st.session_group_help': 'Le applicazioni con lo stesso gruppo (e la directory utenti come autenticazione) condividono l’accesso: dopo aver effettuato l’accesso a una, le altre si aprono senza un nuovo accesso, ciascuna con il proprio controllo di accesso e i propri ruoli; la disconnessione da una disconnette da tutte (APEX: session sharing). Lettere minuscole, cifre e _.',
