  'rs.not_in_query': 'non presente nella query',
  'rpt.report_settings': 'Impostazioni del report',
  'rpt.save_report_settings': 'Salva impostazioni del report',
  'rs.no_position_alert': 'Il report non ha colonne `lat`/`lng` o `location`, quindi l\'area della mappa non può filtrarlo.',
  'rs.facets_help': 'Le caselle mostrano i valori più frequenti (Escludi permette invece di filtrarli via). Intervalli e Da/a richiedono una colonna numerica o data: gli intervalli sono `from..to = label` separati da `;`, con un estremo aperto lasciato vuoto (`..1000`, `2020-01-01..`); un intervallo include l\'inizio, non la fine. Una valutazione a stelle offre «4 stelle e più» e così via (fino a 5; `"max"` nel JSON lo cambia).',
  'rs.facets_help_chart': 'Grafico: un grafico a barre o a torta dei conteggi sotto il facet (compresso); una barra o una fetta filtra sul suo valore.',
  'rs.calendar_help': 'La query restituisce `start_date`, `title` e facoltativamente `end_date` (date per gli eventi di tutto il giorno, timestamp per quelli con un orario).',
  'rs.chart_help': 'La prima colonna è l\'etichetta; ogni colonna numerica successiva è una serie (fino a 8). Un diagramma di Gantt legge `label, start, end` (date o timestamp; una fine vuota è una milestone) e colonne facoltative chiamate `progress` (da 0 a 100), `task_id` e `depends_on` (gli id che un\'attività attende, ad es. `3,4`).',
  'rs.map_help': 'Ogni riga è un indicatore in `lat`, `lng` (o `location` come "lat,lng"), con `title` e `body` nel suo popup; una colonna `geojson` disegna linee e aree (con PostGIS installato va bene anche una colonna `geometry` o `geography` in WGS 84). Una mappa di calore pesa ogni luogo con una colonna `weight`.',
  'rs.tree_help': 'La query restituisce `id`, `parent_id` e `label` (e facoltativamente `icon`); le righe il cui padre non è nel risultato sono le radici.',
  'rs.workflow_help': 'I workflow derivano dalle definizioni di workflow (Componenti condivisi); l\'SQL dell\'applicazione li avvia con `meta.start_workflow(…)`.',
  'rs.task_help': 'Le attività derivano dalle definizioni di attività (Componenti condivisi); l\'SQL dell\'applicazione le crea con `meta.create_task(…)`.',
