  'rm.chk.runs_as': 'I gestori vengono eseguiti come `{role}` con `meta.app_user()` come chiamante',
  'rm.chk.role_problem': 'Il ruolo di database dell\'applicazione: {problem} I suoi gestori rispondono 403.',
  'rm.chk.no_role': 'L\'applicazione non ha un ruolo di database: i gestori vengono eseguiti con il ruolo di runtime di pgkiln. Assegnale un ruolo proprio (Applicazione › Impostazioni) perché permessi e sicurezza a livello di riga siano i suoi.',
  'rm.chk.disabled': 'Disattivato: ogni gestore risponde 404',
  'rm.chk.privilege': 'Privilegio: i chiamanti richiedono il ruolo {roles}',
  'rm.chk.no_privilege': 'Nessun ruolo di privilegio: qualsiasi token valido dell\'applicazione (i gestori possono aggiungere ruoli)',
  'rm.response_as': '{request} come {as}',
  'rm.try_intro': 'Invia la richiesta all\'endpoint reale: un PUT, POST o DELETE modifica i dati. {as} un account emette per esso un token di breve durata, come fa App › REST API; senza, vedi cosa ottiene un chiamante senza token.',
  'rm.intro': 'Moduli dei servizi RESTful: un modulo è un percorso base di un\'applicazione, i suoi modelli sono URI con `:parameters` e ogni modello ha gestori per metodo con la loro origine: una query di raccolta, una riga singola, SQL, un blocco PL/pgSQL o una risorsa multimediale. I gestori vengono eseguiti con il ruolo di database dell\'applicazione e il chiamante come `meta.app_user()`, quindi valgono i suoi permessi e la sicurezza a livello di riga; i parametri sono associati, mai incollati nell\'SQL. Ogni modulo ha un documento OpenAPI. I moduli appartengono alla loro applicazione: viaggiano con la sua esportazione (anche in Componenti condivisi › Servizi RESTful).',
  'rm.source_help': 'Variabili di binding, in maiuscolo: parametri di percorso ({params}), parametri di query e campi del corpo JSON; `:BODY` è l\'intero corpo; `:APP_USER` è il chiamante. I valori sono associati, mai incollati nell\'SQL. PL/pgSQL: un blocco (`declare … begin … end`, o istruzioni) che risponde con `perform meta.rest_reply(jsonb_build_object(…), 201)`. Media: una query che restituisce `content_type`, `content` e facoltativamente `filename`.',
  'rm.params_help': 'Uno per riga: `name query|body [{types}] [required] [description]`. Finiscono nel documento OpenAPI e nel modulo Prova; se ne manca uno obbligatorio, la risposta è 400.',
  'rm.e.params_line': 'Parametri, riga {n}: scrivi "name query" o "name body", poi facoltativamente un tipo ({types}), "required" e una descrizione.',
