  'agt.intro': 'Un agente risponde in una regione di assistente IA e agisce solo tramite gli strumenti che gli dai: query SQL (sola lettura, con il ruolo di database dell\'applicazione, quindi vale la sicurezza a livello di riga), funzioni PL/pgSQL, origini dati REST, azioni JavaScript nel browser e link a pagine (pgkiln costruisce l\'URL e il suo checksum, solo per pagine che l\'utente può aprire). Uno strumento Retrieve dà all\'agente le righe di una configurazione di ricerca che corrispondono a un testo per significato (RAG), sempre con il ruolo dell\'applicazione. Ciò che gli utenti scrivono e i risultati degli strumenti vanno al servizio IA dell\'agente. {usage} elenca ogni chiamata a strumento.',
